/**
 * @file test_ota_verify.c
 * @brief `.ota` vectors generated by `tools/package_ota.py` (cross-check).
 *
 * The fixtures use a TEST Ed25519 key (public) and an AES key derived from
 * "smartlamp-test-aes"; they are not secrets.
 */

#include <stdio.h>
#include <string.h>

#include "unity.h"

#include <sodium.h>

#include "ota.h"

#ifndef OTA_FIXTURE_DIR
#error "OTA_FIXTURE_DIR no definido por CMake"
#endif

#define FIXTURE_BUF 2048U

static uint8_t s_public_key[OTA_PUBLIC_KEY_SIZE];
static uint8_t s_aes_key[OTA_AES_KEY_SIZE];
static uint8_t s_v103[FIXTURE_BUF];
static uint8_t s_v120[FIXTURE_BUF];
static uint8_t s_bad_sig[FIXTURE_BUF];
static uint8_t s_bad_hw[FIXTURE_BUF];
static uint8_t s_payload[FIXTURE_BUF];
static size_t s_v103_len;
static size_t s_v120_len;
static size_t s_bad_sig_len;
static size_t s_bad_hw_len;
static size_t s_payload_len;

static int load_fixture(const char *name, uint8_t *buf, size_t cap,
                        size_t *out_len)
{
    char path[512];
    FILE *fp;
    size_t used;
    int n;

    n = snprintf(path, sizeof(path), "%s/%s", OTA_FIXTURE_DIR, name);
    if ((n <= 0) || ((size_t)n >= sizeof(path))) {
        return -1;
    }
    fp = fopen(path, "rb");
    if (fp == NULL) {
        return -1;
    }
    used = fread(buf, 1U, cap, fp);
    (void)fclose(fp);
    *out_len = used;
    return 0;
}

void setUp(void)
{
    TEST_ASSERT_GREATER_OR_EQUAL_INT(0, sodium_init());
    /* Test AES key: sha256("smartlamp-test-aes"), same as the script. */
    (void)crypto_hash_sha256(s_aes_key, (const unsigned char *)"smartlamp-test-aes",
                             18U);

    TEST_ASSERT_EQUAL_INT(
        0, ota_load_public_key(OTA_FIXTURE_DIR "/test_public.pem", s_public_key));
    TEST_ASSERT_EQUAL_INT(0, load_fixture("test_v1.0.3.ota", s_v103,
                                          sizeof(s_v103), &s_v103_len));
    TEST_ASSERT_EQUAL_INT(0, load_fixture("test_v1.2.0.ota", s_v120,
                                          sizeof(s_v120), &s_v120_len));
    TEST_ASSERT_EQUAL_INT(0, load_fixture("test_bad_signature.ota", s_bad_sig,
                                          sizeof(s_bad_sig), &s_bad_sig_len));
    TEST_ASSERT_EQUAL_INT(0, load_fixture("test_bad_hw.ota", s_bad_hw,
                                          sizeof(s_bad_hw), &s_bad_hw_len));
    TEST_ASSERT_EQUAL_INT(0, load_fixture("test_firmware.bin", s_payload,
                                          sizeof(s_payload), &s_payload_len));
}

void tearDown(void)
{
}

static void test_verify_v1_0_3(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(OTA_OK,
                          ota_verify(s_v103, s_v103_len, &keys, NULL, 1U, &info));
    TEST_ASSERT_EQUAL_UINT16(1U, info.version.major);
    TEST_ASSERT_EQUAL_UINT16(0U, info.version.minor);
    TEST_ASSERT_EQUAL_UINT16(3U, info.version.patch);
    TEST_ASSERT_EQUAL_UINT32(1U, info.hw_compat);
    TEST_ASSERT_EQUAL_UINT32(512U, info.payload_len);
}

static void test_verify_upgrade(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    const ota_version_t active = {1U, 0U, 3U};
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_OK, ota_verify(s_v120, s_v120_len, &keys, &active, 1U, &info));
    TEST_ASSERT_EQUAL_UINT16(1U, info.version.major);
    TEST_ASSERT_EQUAL_UINT16(2U, info.version.minor);
    TEST_ASSERT_EQUAL_UINT16(0U, info.version.patch);
}

static void test_downgrade_rejected(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    const ota_version_t active = {1U, 2U, 0U};
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_FAULT_DOWNGRADE,
        ota_verify(s_v103, s_v103_len, &keys, &active, 1U, &info));
}

static void test_bad_signature_rejected(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_FAULT_SIGNATURE,
        ota_verify(s_bad_sig, s_bad_sig_len, &keys, NULL, 1U, &info));
}

static void test_bad_hardware_rejected(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_FAULT_HARDWARE,
        ota_verify(s_bad_hw, s_bad_hw_len, &keys, NULL, 1U, &info));
}

static void test_truncated_rejected(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_FAULT_FORMAT,
        ota_verify(s_v120, s_v120_len - 1U, &keys, NULL, 1U, &info));
}

static void test_decrypt_payload(void)
{
    const ota_keys_t keys = {s_public_key, s_aes_key};
    const ota_version_t active = {1U, 0U, 3U};
    uint8_t out[FIXTURE_BUF];
    size_t out_len = 0U;
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_OK, ota_verify_decrypt(s_v120, s_v120_len, &keys, &active, 1U, out,
                                   sizeof(out), &out_len, &info));
    TEST_ASSERT_EQUAL_UINT32(512U, out_len);
    TEST_ASSERT_EQUAL_INT(0, memcmp(out, s_payload, out_len));
}

static void test_wrong_aes_key_rejected(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    const ota_version_t active = {1U, 0U, 3U};
    uint8_t wrong_key[OTA_AES_KEY_SIZE];
    uint8_t out[FIXTURE_BUF];
    size_t out_len = 0U;
    ota_info_t info;
    ota_keys_t wrong;

    (void)crypto_hash_sha256(wrong_key, (const unsigned char *)"otra-clave", 10U);
    wrong.public_key = s_public_key;
    wrong.aes_key = wrong_key;

    TEST_ASSERT_EQUAL_INT(
        OTA_FAULT_SIGNATURE,
        ota_verify_decrypt(s_v120, s_v120_len, &wrong, &active, 1U, out,
                           sizeof(out), &out_len, &info));
    (void)keys;
}

static void test_buffer_too_small(void)
{
    const ota_keys_t keys = {s_public_key, s_aes_key};
    uint8_t out[16];
    size_t out_len = 0U;
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_ERR_BUFFER,
        ota_verify_decrypt(s_v120, s_v120_len, &keys, NULL, 1U, out,
                           sizeof(out), &out_len, &info));
}

static void test_invalid_hw_revision_argument(void)
{
    const ota_keys_t keys = {s_public_key, NULL};
    ota_info_t info;

    TEST_ASSERT_EQUAL_INT(
        OTA_ERR_ARGUMENT,
        ota_verify(s_v120, s_v120_len, &keys, NULL, 0U, &info));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_verify_v1_0_3);
    RUN_TEST(test_verify_upgrade);
    RUN_TEST(test_downgrade_rejected);
    RUN_TEST(test_bad_signature_rejected);
    RUN_TEST(test_bad_hardware_rejected);
    RUN_TEST(test_truncated_rejected);
    RUN_TEST(test_decrypt_payload);
    RUN_TEST(test_wrong_aes_key_rejected);
    RUN_TEST(test_buffer_too_small);
    RUN_TEST(test_invalid_hw_revision_argument);
    return UNITY_END();
}
